## Impact
Having no access control on this crucial function, means that attacker can either set the protocol fee to 0 and not pay fee or increase the fee to grief other users.

## Proof of Concept
If we take a look at the other 2 functions that are part of the interface, we can see the validation for caller:

```solidity
    function collectProtocol(
        address recipient,
        uint128 amount0Requested,
        uint128 amount1Requested
    ) external override lock returns (uint128 amount0, uint128 amount1) {
        require(msg.sender == IRamsesV3Factory(factory).feeCollector(), ProtocolActions.Unauthorized());

        return ProtocolActions.collectProtocol(recipient, amount0Requested, amount1Requested, token0, token1);
    }
```

```solidity
    function setFee(uint24 _fee) external override lock {
        ProtocolActions.setFee(_fee, factory);
    }
```

```solidity
    function setFee(uint24 _fee, address factory) external {
        PoolStorage.PoolState storage $ = PoolStorage.getStorage();
        if (msg.sender != factory) revert Unauthorized();
        if (_fee > 100000) revert InvalidFee();
        uint24 _oldFee = $.fee;
        $.fee = _fee;
        emit FeeAdjustment(_oldFee, _fee);
    }
```

Now lets look at the vulnerable `setFeeProtocol` function:

```solidity
    function setFeeProtocol() external override lock {
        ProtocolActions.setFeeProtocol(factory);
    }
```

```solidity
    function setFeeProtocol(address factory) external {
        PoolStorage.PoolState storage $ = PoolStorage.getStorage();

        uint8 feeProtocolOld = $.slot0.feeProtocol;

        uint8 feeProtocol = IRamsesV3Factory(factory).poolFeeProtocol(address(this));

        if (feeProtocol != feeProtocolOld) {
            $.slot0.feeProtocol = feeProtocol;
