    function _distribute(
        address _gauge,
        uint256 _claimable,
        uint256 _period
    ) internal nonReentrant {
        if (isAlive[_gauge]) {
            if (_claimable == 0) return;

            if (gaugePeriodDistributed[_gauge][_period]) return;

            /// @dev can only distribute if the distributed amount / week > 0 and is > left()
            bool canDistribute = true;

            if (_claimable > 0) {
                if (
                    _claimable / DURATION == 0 ||
                    _claimable < IGauge(_gauge).left(emissionsToken)
                ) {
                    canDistribute = false;
                }
            }

            if (canDistribute) {
                gaugePeriodDistributed[_gauge][_period] = true;

                if (_claimable > 0) {
                    /// @dev notify emissions
                    IGauge(_gauge).notifyRewardAmount(
                        emissionsToken,
                        _claimable
                    );
                }

                emit DistributeReward(msg.sender, _gauge, _claimable);
            }
        }
    }
```

The problem is that any rewards sent to the gauge prior to its first depositor will remain permanently stuck. Given that rewards are sent automatically, the likelihood of such occurrence is significantly higher.


